/// <summary>
/// Vendor rebate line contract 
/// </summary>
[DataContractAttribute]
public class METVendorRebateTableContract
{
    TAMRebateId tamRebateId;
    Description description;
    TAMRebateCalcMethod tamRebateCalcMethod;
    ModuleInventCustVend moduleInventCustVend;
    TAMRebateAvgPurchPriceNoOfMonths tamRebateAvgPurchPriceNoOfMonths;
    TAMRebateMinAmount tamRebateMinAmount;
    InventSiteId inventSiteId;
    TAMRebateDealId tamRebateDealId;
    UnitOfMeasureSymbol unitOfMeasureSymbol;

    const str agreementDescription = "AgreementDescription";
    const str agreementNumber = "AgreementNumber";
    const str calculationMethod = "CalculationMethod";
    const str agreementModule = "AgreementModule";
    const str avgPurchPriceNoOfMonths = "AveragePurchasePriceBasisCalculationMonthRange";
    const str minimumAmount = "MinimumAmount";
    const str operationalSiteId = "OperationalSiteId";
    const str rebateAndDeductionsDealNumber = "RebateAndDeductionsDealNumber";
    const str unitSymbol = "UnitSymbol";



}

